import type * as Channel3Api from "../index.js";
/**
 * A single click event.
 */
export interface Click {
    /** Click event ID. */
    id: string;
    /** When the click occurred, returned with a UTC offset (Z). */
    timestamp: Date;
    /** Partner-supplied user identifier from the buy URL, if provided. */
    user_id?: string | null;
    /** Matched product, if known. */
    product?: Channel3Api.ReportingProduct | null;
    /** Click city, if available. */
    city?: string | null;
    /** Click country, if available. */
    country?: string | null;
}
